class Solution {
    int get_diameter(const vector<vector<int>>& edges) {
        int n = edges.size() + 1;
        if (n <= 1) return 0;
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        auto bfs = [&](int start) -> pair<int, int> {
            vector<int> dist(n, -1);
            dist[start] = 0;
            queue<int> q;
            q.push(start);
            int farthest = start;
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                for (int v : adj[u]) {
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        q.push(v);
                        if (dist[v] > dist[farthest]) farthest = v;
                    }
                }
            }
            return {farthest, dist[farthest]};
        };
        auto [u, _] = bfs(0);
        auto [__, diam] = bfs(u);
        return diam;
    }
public:
