class Solution {
    private int getDiameter(int[][] edges) {
        int n = edges.length + 1;
        if (n <= 1) return 0;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; ++i) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        int[] first = bfs(0, adj, n);
        int[] second = bfs(first[0], adj, n);
        return second[1];
    }
    private int[] bfs(int start, List<Integer>[] adj, int n) {
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[start] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(start);
        int farthest = start;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.offer(v);
                    if (dist[v] > dist[farthest]) farthest = v;
                }
            }
        }
        return new int[]{farthest, dist[farthest]};
    }
    public int minimumDiameterAfterMerge(int[][] edges1, int[][] edges2) {
        int d1 = getDiameter(edges1);
        int d2 = getDiameter(edges2);
        int r1 = (d1 + 1) / 2;
        int r2 = (d2 + 1) / 2;
        return Math.max(Math.max(d1, d2), r1 + r2 + 1);
    }
}

